<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_permission('view_stock_reports');
[$scope,$params]=location_scope_sql('ib.location_id');$st=db()->prepare('SELECT p.sku,p.product_name,SUM(ib.qty) physical,SUM(ib.reserved_qty) reserved,SUM(GREATEST(ib.qty-ib.reserved_qty,0)) sellable,p.min_stock FROM inventory_balances ib JOIN products p ON p.id=ib.product_id WHERE 1=1'.$scope.' GROUP BY p.id HAVING sellable<=p.min_stock ORDER BY sellable ASC LIMIT 500');$st->execute($params);$low=$st->fetchAll();
$st=db()->prepare('SELECT sl.created_at,p.sku,p.product_name,p.color,p.size,l.code location_code,sl.qty_out,sl.reference_type,sl.remarks FROM stock_ledger sl JOIN products p ON p.id=sl.product_id JOIN locations l ON l.id=sl.location_id WHERE sl.txn_type=\'DAMAGE\''.str_replace('ib.location_id','sl.location_id',$scope).' ORDER BY sl.id DESC LIMIT 200');$st->execute($params);$damaged=$st->fetchAll();
$st=db()->prepare('SELECT p.sku,p.product_name,p.color,p.size,b.batch_no,b.purchased_at,l.code location_code,ib.qty physical,ib.reserved_qty reserved,GREATEST(ib.qty-ib.reserved_qty,0) sellable,DATEDIFF(CURDATE(),b.purchased_at) age_days FROM inventory_balances ib JOIN products p ON p.id=ib.product_id JOIN batches b ON b.id=ib.batch_id JOIN locations l ON l.id=ib.location_id WHERE ib.qty>0'.$scope.' ORDER BY age_days DESC LIMIT 500');$st->execute($params);$aging=$st->fetchAll();
$st=db()->prepare('SELECT sl.created_at,sl.txn_type,p.sku,p.product_name,b.batch_no,l.code location_code,sl.qty_in,sl.qty_out,sl.reference_type,sl.reference_id,sl.remarks FROM stock_ledger sl JOIN products p ON p.id=sl.product_id JOIN batches b ON b.id=sl.batch_id JOIN locations l ON l.id=sl.location_id WHERE 1'.str_replace('ib.location_id','sl.location_id',$scope).' ORDER BY sl.id DESC LIMIT 500');$st->execute($params);$ledger=$st->fetchAll();
$transferScope='';$transferArgs=[];if(!is_super_admin()){$ids=assigned_location_ids();if(!$ids){$transferScope=' AND 1=0';}else{$ph=implode(',',array_fill(0,count($ids),'?'));$transferScope=" AND (t.from_location_id IN ($ph) OR t.to_location_id IN ($ph))";$transferArgs=array_merge($ids,$ids);}}
$st=db()->prepare("SELECT t.transfer_no,lf.code from_code,lt.code to_code,t.dispatched_at,(SELECT COUNT(*) FROM stock_transfer_items i WHERE i.transfer_id=t.id) line_count,(SELECT COALESCE(SUM(i.quantity),0) FROM stock_transfer_items i WHERE i.transfer_id=t.id) qty FROM stock_transfers t JOIN locations lf ON lf.id=t.from_location_id JOIN locations lt ON lt.id=t.to_location_id WHERE t.status='DISPATCHED'".$transferScope.' ORDER BY t.dispatched_at');$st->execute($transferArgs);$inTransit=$st->fetchAll();
$st=db()->prepare("SELECT t.transfer_no,lf.code from_code,lt.code to_code,t.received_at,t.notes FROM stock_transfers t JOIN locations lf ON lf.id=t.from_location_id JOIN locations lt ON lt.id=t.to_location_id WHERE t.has_discrepancy=1".$transferScope.' ORDER BY t.received_at DESC LIMIT 200');$st->execute($transferArgs);$discrepancies=$st->fetchAll();
page_header('Stock Reports / Ledger');?>
<h2>Low Sellable Stock</h2><table><tr><th>SKU</th><th>Product</th><th>Physical</th><th>Reserved</th><th>Sellable</th><th>Minimum</th></tr><?php foreach($low as $r):?><tr><td><?=e($r['sku'])?></td><td><?=e($r['product_name'])?></td><td><?=e($r['physical'])?></td><td><?=e($r['reserved'])?></td><td><?=e($r['sellable'])?></td><td><?=e($r['min_stock'])?></td></tr><?php endforeach;?></table><br><h2>Stock by Location &amp; Aging</h2><table><tr><th>SKU</th><th>Product</th><th>Colour / Size</th><th>Batch</th><th>Location</th><th>Physical</th><th>Reserved</th><th>Sellable</th><th>Age Days</th></tr><?php foreach($aging as $r):?><tr><td><?=e($r['sku'])?></td><td><?=e($r['product_name'])?></td><td><?=e(trim($r['color'].' / '.$r['size'],' /'))?></td><td><?=e($r['batch_no'])?></td><td><?=e($r['location_code'])?></td><td><?=e($r['physical'])?></td><td><?=e($r['reserved'])?></td><td><?=e($r['sellable'])?></td><td><?=e($r['age_days'])?></td></tr><?php endforeach;?></table><br><h2>Damaged / Not Sellable (latest)</h2><table><tr><th>Date</th><th>SKU</th><th>Product</th><th>Colour / Size</th><th>Location</th><th>Qty</th><th>Source</th><th>Reason</th></tr><?php foreach($damaged as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['sku'])?></td><td><?=e($r['product_name'])?></td><td><?=e(trim($r['color'].' / '.$r['size'],' /'))?></td><td><?=e($r['location_code'])?></td><td><?=e($r['qty_out'])?></td><td><?=e($r['reference_type'])?></td><td><?=e($r['remarks'])?></td></tr><?php endforeach; if(!$damaged):?><tr><td colspan="8" class="muted">No damaged stock recorded.</td></tr><?php endif;?></table><br><h2>Latest Stock Ledger</h2><table><tr><th>Date</th><th>Type</th><th>Product</th><th>Batch</th><th>Location</th><th>In</th><th>Out</th><th>Reference</th><th>Remarks</th></tr><?php foreach($ledger as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['txn_type'])?></td><td><?=e($r['sku'].' · '.$r['product_name'])?></td><td><?=e($r['batch_no'])?></td><td><?=e($r['location_code'])?></td><td><?=e($r['qty_in'])?></td><td><?=e($r['qty_out'])?></td><td><?=e(($r['reference_type']??'').' '.($r['reference_id']??''))?></td><td><?=e($r['remarks'])?></td></tr><?php endforeach;?></table><br>
<h2>Stock In Transit (Dispatched, Not Yet Received)</h2><table><tr><th>Transfer</th><th>From → To</th><th>Lines</th><th>Qty</th><th>Dispatched At</th></tr><?php foreach($inTransit as $r):?><tr><td><?=e($r['transfer_no'])?></td><td><?=e($r['from_code'])?> → <?=e($r['to_code'])?></td><td><?=e($r['line_count'])?></td><td><?=e(number_format((float)$r['qty'],3))?></td><td><?=e($r['dispatched_at'])?></td></tr><?php endforeach; if(!$inTransit):?><tr><td colspan="5" class="muted">Nothing currently in transit.</td></tr><?php endif;?></table><br>
<h2>Transfer Discrepancies</h2><table><tr><th>Transfer</th><th>From → To</th><th>Received At</th><th>Notes</th></tr><?php foreach($discrepancies as $r):?><tr><td><?=e($r['transfer_no'])?></td><td><?=e($r['from_code'])?> → <?=e($r['to_code'])?></td><td><?=e($r['received_at'])?></td><td><?=e($r['notes'])?></td></tr><?php endforeach; if(!$discrepancies):?><tr><td colspan="4" class="muted">No transfer discrepancies recorded.</td></tr><?php endif;?></table><?php page_footer();
